using FriendInfo=OpenSim.Services.Interfaces.FriendInfo;using System;using System.Collections.Generic;using System.Text;using Nini.Config;using OpenMetaverse;using OpenSim.Data;using OpenSim.Services.Interfaces;using OpenSim.Services.Friends;
namespace Nini.Config{public interface IConfigSource{}}
namespace log4net{public class Placeholder{}}
namespace OpenSim.Framework{public static class Util{public static bool ParseUniversalUserIdentifier(string value,out UUID uuid){uuid=UUID.Zero;if(value==null||value.Length<36)return false;return UUID.TryParse(value.Length==36?value:value[..36],out uuid);}}}
namespace OpenSim.Services.Friends{public class FriendsServiceBase{protected IFriendsData m_Database;public FriendsServiceBase(IConfigSource config){m_Database=Program.Store;}}}
class FixtureStore:IFriendsData{public int Seed;public string Trace="";public FixtureStore(int s){Seed=s;}public FriendsData[] Rows(){int kind=Seed%12;if(kind==1)return Array.Empty<FriendsData>();if(kind==2)throw new Exception();if(kind==3)return new FriendsData[]{null};var r=new FriendsData{PrincipalID=kind==4?null:kind==5?"bad":Program.Id(1).ToString(),Friend=kind==6?null:Program.Id(2)+";https://grid/;Friend Name"};if(kind!=7){r.Data=new();if(kind!=8)r.Data["Flags"]=kind==10?null:kind==9?"bad":"7";r.Data["TheirFlags"]=kind==11?"2147483648":"-1";}return new[]{r,r};}
 public FriendsData[] GetFriends(UUID p){Trace+="uuid;";return Rows();}public FriendsData[] GetFriends(string p){Trace+="string:"+Program.Hex(p)+";";return Rows();}
 public bool Store(FriendsData r){Trace+="store:"+Program.Hex(r.PrincipalID)+":"+Program.Hex(r.Friend)+":"+Program.Hex(r.Data["Flags"])+";";if((Seed&2)!=0)throw new Exception();return (Seed&1)!=0;}
 public bool Delete(UUID p,string f){Trace+="delete-uuid:"+Program.Hex(f)+";";if((Seed&2)!=0)throw new Exception();return (Seed&1)!=0;}public bool Delete(string p,string f){Trace+="delete-string:"+Program.Hex(p)+":"+Program.Hex(f)+";";if((Seed&2)!=0)throw new Exception();return (Seed&1)!=0;}}
class Program{public static FixtureStore Store;public static UUID Id(int n)=>new UUID("00000000-0000-0000-0000-"+n.ToString("x12"));public static string Hex(string s)=>s==null?"-":s.Length==0?".":Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();static void Main(){string line;while((line=Console.ReadLine())!=null){var p=line.Split(' ');int mode=int.Parse(p[0]),seed=int.Parse(p[1]);Store=new(seed);var service=new FriendsService(null);string output;try{if(mode<2){var rows=mode==1?service.GetFriends("principal"):service.GetFriends(Id(1));output=rows.Length.ToString();foreach(var r in rows)output+="|"+r.PrincipalID+":"+Hex(r.Friend)+":"+r.MyFlags+":"+r.TheirFlags;}else if(mode<5){string principal=(seed&4)!=0?null:"principal",f=(seed&8)!=0?null:"friend";bool okay=mode==2?service.StoreFriend(principal,f,seed%2!=0?-2147483647:2147483647):mode==3?service.Delete(Id(1),f):service.Delete(principal,f);output=okay?"T":"F";}else{var values=new Dictionary<string,object>{{"PrincipalID",seed%3==0?"bad":Id(1).ToString()},{"MyFlags",(seed-32).ToString()},{"TheirFlags",seed%2!=0?"bad":"2147483647"}};if(seed%4!=0)values["Friend"]="friend";var f=new FriendInfo(values);output=f.PrincipalID+":"+Hex(f.Friend)+":"+f.MyFlags+":"+f.TheirFlags+":"+f.ToKeyValuePairs().Count;}}catch{output="E";}Console.WriteLine(Store.Trace+"|"+output);}}}
